head.script:
scwin.screenId = "jlddst05601";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "slc_selYear", attr: "__items", fn: function () { return [[String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("viewYear"))), String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("viewYear")))]]; } },
        { childId: "slc_selMonth", attr: "__items", fn: function () { return [["", String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("j")))]]; } },
        { childId: "imgMonth", attr: "name", fn: function () { return "imgMonth" + String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("idNumber"))); } },
        { childId: "imgMonth", attr: "toolTip", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("idx"))) + "월"; } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("idx"))) + "월"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $("#searchForm").find("select[name=slc_selYear]").val('null');
        await scwin.fnCalCheck('null');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05601.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst05601.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_selYear_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_selYear_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_selYear_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnCalcSearch();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05601.slc_selYear_onchange' }); }
};

/**
 * @event
 * @name scwin.slc_selMonth_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_selMonth_onchange = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_selMonth_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnCalCheck(selfVar.value);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05601.slc_selMonth_onchange' }); }
};

/**
 * @event
 * @name scwin.imgMonth_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.imgMonth_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin imgMonth_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnCalCheck('' + dma_pageContext.get("idNumber") + ''); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05601.imgMonth_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_fnCalcSearch_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnCalcSearch_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnCalcSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnCalcSearch(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst05601.btn_fnCalcSearch_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnMoveIRSchedule
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnMoveIRSchedule = async function () {
    const sbmOptions = {
        id: "tx_fnMoveIRSchedule",
        method: "post",
        action: "/corpgeneral/irschedule.do",
        ref: "dma_fnMoveIRScheduleReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst05601.tx_fnMoveIRSchedule" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnCalcSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnCalcSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnCalcSearch_ajaxsubmit",
        method: "post",
        action: "/corpgeneral/irschedule.do",
        ref: "dma_fnCalcSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst05601.tx_fnCalcSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnCalcSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnCalcSearch = async function () {
    /* sdd-asis-lifecycle:begin fnCalcSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnMoveIRScheduleReq").set("method", "searchIRScheduleCalendar");
    await scwin.tx_fnCalcSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnCalCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.fnCalCheck = async function (val) {
    /* sdd-asis-lifecycle:begin fnCalCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let idx = 1; idx <= 12; idx++) {
        let classid = "ord-";
        if ((idx - 1) >= 10) {
            classid += (idx - 1);
        } else {
            classid += "0" + (idx - 1);
        }
        if (val === idx) {
            classid += " active";
        }
        let idName = "imgMonth";
        if (idx >= 10) {
            idName += idx;
        } else {
            idName += "0" + idx;
        }
        $('#searchForm').find('a[name="' + idName + '"]').attr('class', classid);
    }
    $("#searchForm").find("select[name=slc_selMonth]").val(val);
    await scwin.fnCalcSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnPopupIRInfoDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.fnPopupIRInfoDetail = async function (val) {
    /* sdd-asis-lifecycle:begin fnPopupIRInfoDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const me = await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })('/corpgeneral/irschedule.do?method=searchIRSchedulePopup&irSeq=' + val), { id: 'IR정보상세검색', width: '600', height: '400' }, {});
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnMoveIRSchedule
 * @author Inswave
 * @date 2026. 09. 29
 * @param val
 * @returns
 * @hidden N
*/
scwin.fnMoveIRSchedule = async function (val) {
    /* sdd-asis-lifecycle:begin fnMoveIRSchedule — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const year = $("#searchForm").find("select[name=slc_selYear]").val();
    const month = $("#searchForm").find("select[name=slc_selMonth]").val();
    $c.util.getComponent("dma_fnMoveIRScheduleReq").set("searchFromDate", year + "-" + month + "-" + val);
    $c.util.getComponent("dma_fnMoveIRScheduleReq").set("searchToDate", year + "-" + month + "-" + val);
    $c.util.getComponent("dma_fnMoveIRScheduleReq").set("method", "searchIRScheduleMain");
    $c.util.getComponent("dma_fnMoveIRScheduleReq").set("gubun", "iRSchedule");
    await scwin.tx_fnMoveIRSchedule();
    /* sdd-asis-lifecycle:end */
};
